import {INSTRUMENT,CONSENT,QUESTIONS,DIMENSIONS,QUESTION_ORDER,diagnose,validAnswers,encodeResult,readResultLink,compareResults} from './diagnosis.mjs';
import {CHAPTERS} from './content.mjs';
import {GROUPS,normalizeLabel,organizeTags} from './tags.mjs';
const SITEKEY='0x4AAAAAAFaMaq3Xy2r-CpoC';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PENDING='heki16_pending_partner_v1';
const KEY='heki16_unified40_v1',RECEIPT='heki16_research_receipt_v1';
const empty=()=>({instrument:INSTRUMENT,mode:40,answers:Array(40).fill(null),index:0,complete:false,tags:[],learned:{},adult:false});
let state=empty(),sample=false,shared=null,pendingPartner='',undoTags=null,receipt=null,toastTimer,activeWidget=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.instrument===INSTRUMENT&&validAnswers(saved.answers)&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<40)state={...empty(),...saved,tags:organizeTags(Array.isArray(saved.tags)?saved.tags:[]),learned:saved.learned&&typeof saved.learned==='object'?saved.learned:{}};else{const previous=JSON.parse(localStorage.getItem('heki16_reflection_v2')||localStorage.getItem('heki16_reflection_v1'));if(previous?.tags)state.tags=organizeTags(previous.tags);}receipt=JSON.parse(localStorage.getItem(RECEIPT));}catch{}
try{const pending=sessionStorage.getItem(PENDING);if(pending&&pending.length<=12000&&pending.split('\n').length<=3){pending.split('\n').forEach(readResultLink);pendingPartner=pending;}}catch{}
const keepPartner=value=>{pendingPartner=value;try{sessionStorage.setItem(PENDING,value);}catch{}};
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{$('#storage-warning').hidden=false;}};
const say=text=>{clearTimeout(toastTimer);$('#status').textContent=text;toastTimer=setTimeout(()=>$('#status').textContent='',5000);};
const button=(label,action,kind='')=>`<button class="btn ${kind}" data-action="${action}">${label}</button>`;
function close(){if(activeWidget!==null&&window.turnstile){window.turnstile.remove(activeWidget);activeWidget=null;}$('#modal').close();}
$('#modal').addEventListener('close',()=>{if(activeWidget!==null&&window.turnstile){window.turnstile.remove(activeWidget);activeWidget=null;}});
function modal(title,body){$('#modal-body').innerHTML=`<h2 id="modal-title">${esc(title)}</h2>${body}`;$('#modal').showModal();}
const navigate=route=>location.hash==='#'+route?render():location.hash=route;
const initialHome=$('#main').innerHTML;
const sampleAnswers=(()=>{const a=Array(40).fill(2);for(const n of [1,3,5,12,14,15,17,22,24,25,27,33,35,38])a[n-1]=4;for(const n of [2,6,9,10,11,13,31,34,39])a[n-1]=1;for(const n of [4,19,26,29,30])a[n-1]=3;a[31]=4;a[7]=0;a[35]=0;a[36]=1;a[39]=0;return a;})();
const ownResult=()=>diagnose(state.answers),currentResult=()=>shared||(sample?diagnose(sampleAnswers):ownResult());
const currentTags=()=>shared?shared.tags:sample?organizeTags(['焦らしと翻弄','温度差に弱い','褒めに弱い']):state.tags;
function home(){const count=state.answers.filter(v=>v!==null).length;return initialHome.replace('<!--DRAFT-->',!state.complete&&count?`<div class="resume-row"><p>${count}問の回答を残しています。</p>${button('続きから答える','resume','plain')}</div>`:'')+$('#home-ad').innerHTML+(receipt?`<details class="quiet-tools"><summary>提供した回答について</summary><div class="actions">${button('提供を取り消す','withdraw')}${button('控えを保存','backup')}</div></details>`:'');}
function start(){modal('あなたの性癖を、40問で。',`<p>合意した成人同士の場面を想像して、自分が「したい・されたい」方で答えてください。実体験がなくても大丈夫です。</p><p>迷う問いは飛ばせます。途中で休んでも、続きから答えられます。</p>${state.complete?'<p class="muted">回答を作り直します。追加したタグは引き継ぎます。</p>':''}<label class="check"><input type="checkbox" id="adult-check"><span>18歳以上です。</span></label><p id="start-error" class="error" role="alert"></p><div class="actions">${button('診断を始める','confirm-start','primary')}${button('戻る','close','plain')}</div>`);}
function quiz(){const q=QUESTIONS[QUESTION_ORDER[state.index]],answer=state.answers[q.id];return `<section class="quiz"><div class="quiz-top"><span>${state.index+1} / 40</span><button class="text-btn" data-action="pause">中断する</button></div><progress value="${state.index}" max="40" aria-label="質問の進み具合"></progress><div class="question-sheet"><p class="chapter-name">${esc(CHAPTERS[q.chapter])}</p><h1 id="question-title" tabindex="-1">${esc(q.text)}</h1><fieldset class="choices ${q.kind}"><legend>${q.kind==='scene'?'自分が入りたい場面を一つ':'いちばん近い反応を一つ'}</legend>${q.choices.map(c=>`<label class="choice"><input type="radio" name="answer" value="${c.value}" ${answer===c.value?'checked':''}><span class="choice-content"><span>${esc(c.label)}</span>${c.degree?`<small>${esc(c.degree)}</small>`:''}</span></label>`).join('')}</fieldset><div class="quiz-nav"><button class="btn plain" data-action="previous" ${state.index===0?'disabled':''}>戻る</button><button class="btn primary" data-action="next" ${answer===null?'disabled':''}>${state.index===39?'結果を見る':'次へ'}</button></div><button class="text-btn skip-question" data-action="skip">まだわからない・答えずに進む</button></div></section>`;}
function advance(skip=false){const id=QUESTION_ORDER[state.index];if(skip)state.answers[id]=null;if(!skip&&state.answers[id]===null)return;if(state.index<39){state.index++;persist();render();}else{state.complete=true;persist();navigate('profile');}}
function traits(r){return [['主導権とS/M',['lead','yield','sadism','masochism']],['関係の温度',['wet','cool']],['刺さる入口と余韻',['narrative','aesthetic','extreme','pamper']]].map(([title,ids])=>`<details class="trait-section"><summary><strong>${title}</strong><span class="disclosure-hint">詳しく見る</span></summary><div class="detail-body trait-grid">${ids.map(id=>{const d=r.dims.find(x=>x.id===id);return `<div class="trait"><div class="row"><h3>${esc(d.label)}</h3><span>${d.n<3?'まだわからない':d.level}</span></div><p class="trait-description">${esc(d.description)}</p><meter min="0" max="100" value="${d.score??0}" aria-label="${esc(d.label)}" ${d.n<3?'class="unknown"':''}></meter>${d.n>=3?`<span class="trait-score">${d.score} / 100</span>`:''}</div>`;}).join('')}</div></details>`).join('');}
function tagEditor(){const tags=currentTags(),readonly=!!shared||sample,ideas=currentResult().triggers.map(t=>t.label).filter(label=>!tags.some(t=>t.label===label));return `<section class="panel tag-panel"><div class="row"><h2>${readonly?(shared?'共有された言葉':'見本のタグ'):'自分の言葉を、足してみる。'}</h2>${!readonly?'<button class="text-btn" data-action="organize">整理する</button>':''}</div>${!readonly?`<form id="tag-form" class="tag-form"><label class="sr-only" for="tag-input">タグを追加</label><input id="tag-input" maxlength="32" placeholder="例：声フェチ、わからせられたい" autocomplete="off"><label class="sr-only" for="tag-kind">タグの種類</label><select id="tag-kind"><option value="like">好き</option><option value="boundary">避けたい</option></select><button class="btn primary">追加</button></form>${ideas.length?`<div class="tag-ideas"><p class="muted">しっくりきた言葉を選んで追加</p><div class="tags">${ideas.slice(0,4).map(label=>`<button class="tag" data-suggest-tag="${esc(label)}">＋ ${esc(label)}</button>`).join('')}</div></div>`:''}`:''}<div class="tag-groups">${!tags.length?'<p class="tag-empty">まだタグはありません。あなたの「好き」を書き足せます。</p>':''}${Object.entries(GROUPS).filter(([id])=>tags.some(t=>t.group===id)).map(([id,label])=>`<section class="tag-group"><h3>${label}</h3><div class="tags">${tags.map((t,i)=>t.group===id?readonly?`<span class="tag ${t.kind}">${t.kind==='boundary'?'避けたい：':''}${esc(t.label)}</span>`:`<button class="tag ${t.kind}" data-tag="${i}" aria-label="${esc(t.label)}を編集">${t.kind==='boundary'?'避けたい：':''}${esc(t.label)}</button>`:'').join('')}</div></section>`).join('')}</div>${!readonly?`<div class="row"><small>${tags.length} / 24タグ · タップして編集</small>${undoTags?'<button class="text-btn" data-action="undo-tags">元に戻す</button>':''}</div>`:''}</section>`;}
function profile(){if(!state.complete&&!sample&&!shared)return `<section class="hero"><h1>あなたは、どの性癖タイプ？</h1><p>40問から、刺さる関係と裏のスイッチを見つけよう。</p><div class="actions">${button('性癖を診断する','start','primary')}${button('結果の見本を見る','sample','plain')}</div></section>`;const r=currentResult();return `<section class="result-cover"><div class="result-context">${shared?'相手の性癖タイプ':sample?'結果の見本':'あなたの性癖タイプ'}${r.typeCode?`<span class="type-code">${r.typeCode}</span>`:''}</div><h1>${esc(r.title)}</h1><p class="result-description">${esc(r.description)}</p>${r.shadow?`<div class="shadow-line"><p class="shadow-label">裏スイッチ</p><p>${esc(r.shadow.text)}</p></div>`:''}${r.triggers.length?`<div class="tags result-triggers" aria-label="刺さる要素">${r.triggers.slice(0,3).map(t=>`<span class="tag">${esc(t.label)}</span>`).join('')}</div>`:''}<div class="actions result-actions">${button('結果を画像でシェア','share','primary')}${button(shared?(state.complete?'自分の結果と比べる':'自分も診断して比べる'):'相性を見てみる','compare','plain')}</div>${sample?`<button class="text-btn" data-action="start">自分の性癖を診断する</button>`:''}</section><section class="result-details" aria-label="性癖をもっと知る">${traits(r)}</section>${tagEditor()}${$('#result-ad').innerHTML}${!sample&&!shared?`<details class="quiet-tools"><summary>回答を見直す・保存する</summary><div class="actions">${button('回答を見直す','review')}${button('データを保存','backup')}${button('回答を消す','reset','plain')}</div></details><details class="quiet-tools"><summary>診断づくりに協力する</summary><p>希望する方は、回答を改善のために提供できます。名前や自由に書いたタグは送りません。</p>${receipt?(receipt.pending?button('提供をもう一度試す','research'):'')+button('提供を取り消す','withdraw'):SITEKEY?button('協力内容を確認する','research'):''}<button class="text-btn" data-action="reference">みんなの回答を見る</button><p id="reference-result" role="status"></p></details>`:''}`;}
function editTag(index){const t=state.tags[index];if(!t)return;modal('タグを整える',`<label class="label" for="edit-label">あなたの言葉</label><input id="edit-label" maxlength="32" value="${esc(t.label)}"><label class="label" for="edit-group">置く場所</label><select id="edit-group">${Object.entries(GROUPS).map(([id,label])=>`<option value="${id}" ${t.group===id?'selected':''}>${label}</option>`).join('')}</select><label class="label" for="edit-kind">種類</label><select id="edit-kind"><option value="like" ${t.kind==='like'?'selected':''}>好き・大切</option><option value="boundary" ${t.kind==='boundary'?'selected':''}>今は避けたい</option></select><div class="actions" style="margin-top:24px">${button('保存する','save-tag','primary')}${button('削除する','delete-tag','plain')}</div>`);$('#modal').dataset.tag=index;}

function compare(){const partnerTitles=pendingPartner?pendingPartner.split('\n').map(s=>readResultLink(s).title):[];const own=sample?encodeResult(diagnose(sampleAnswers)):state.complete?encodeResult(ownResult()):'';return `<section class="compare-heading"><h1>二人なら、どんな関係？</h1><p>主導権、駆け引き、甘やかし方。<br>好きな人や友人の結果と比べてみよう。</p></section>${!own?`<div class="notice"><p>先に自分の性癖を診断すると、相手の結果と比べられます。</p>${button('自分も診断する','start','primary')}</div>`:''}<section class="panel compare-form">${own?'<p>この結果と比べます。</p><details><summary>自分の結果を貼り直す</summary>':''}<label class="label" for="own-code">自分の共有URL</label><input id="own-code" placeholder="診断結果の共有URL" value="${esc(own)}">${own?'</details>':''}${partnerTitles.length?`<p class="received-result">受け取った相手：<strong>${partnerTitles.map(esc).join('、')}</strong></p><details><summary>別の結果を貼る・人数を増やす</summary>`:''}<label class="label" for="partner-codes">相手から受け取った共有URL</label><textarea id="partner-codes" rows="3" placeholder="ここに貼り付ける">${esc(pendingPartner)}</textarea><p class="muted">最大3人。複数なら、1人ずつ改行してください。</p>${partnerTitles.length?'</details>':''}<div class="actions">${button('相性を見てみる','run-compare','primary')}</div><p id="compare-error" class="error" role="alert"></p></section><div id="comparison" tabindex="-1"></div>`;}
function runCompare(){try{const mine=readResultLink($('#own-code').value),lines=$('#partner-codes').value.split(/\n/).filter(s=>s.trim());if(lines.length<1||lines.length>3)throw Error('相手の共有URLを1〜3人分、1人ずつ改行して入れてください。');const all=[mine,...lines.map(readResultLink)];keepPartner(lines.join('\n'));let html=all.length>2?'<p class="group-count">'+(all.length*(all.length-1)/2)+'組の組み合わせ</p>':'';for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++){const a=all[i],b=all[j],aLabel=i===0?'あなた':'相手'+i,insights=compareResults(a,b,{aLabel,bLabel:'相手'+j});const heading='<p class="pair-label">'+aLabel+' × 相手'+j+'</p><h2>'+esc(a.title)+'<span class="pair-times"> × </span>'+esc(b.title)+'</h2>';const body=insights.map(line=>'<article class="pair-insight"><h3>'+esc(line.title)+'</h3><p>'+esc(line.text)+'</p></article>').join('')+(a.tags.length||b.tags.length?'<details><summary>共有されたタグ</summary><p>'+a.tags.concat(b.tags).map(t=>esc((t.kind==='boundary'?'避けたい：':'')+t.label)).join(' ／ ')+'</p></details>':'');html+=all.length>2?'<details class="panel pair-result group-pair"><summary>'+heading+'<p class="group-hook">'+esc(insights[0].title)+'</p><span class="disclosure-hint">組み合わせを見る</span></summary><div class="pair-body">'+body+'</div></details>':'<section class="panel pair-result">'+heading+body+'</section>';}$('#comparison').innerHTML=html;$('#compare-error').textContent='';$('#comparison').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});$('#comparison').focus({preventScroll:true});}catch(e){$('#compare-error').textContent=e.message;}}
function share(){const r=currentResult(),suggested=r.triggers.slice(0,3).map(t=>({label:t.label,kind:'like'})),tags=organizeTags([...suggested,...currentTags()]);modal('この内容で、シェアする。',`<p>タイプと性癖の傾向を共有します。タグは3つまで選べます。リンクを知る人は、内容を保存・転送できます。</p><canvas id="share-canvas" width="1200" height="630" aria-label="共有する診断結果の画像"></canvas><details class="share-tag-picker"><summary>画像に載せるタグを選ぶ</summary><div id="share-tags">${tags.map((t,i)=>`<label class="check"><input type="checkbox" data-share-tag="${i}" ${i<suggested.length?'checked':''}><span>${t.kind==='boundary'?'避けたい：':''}${esc(t.label)}</span></label>`).join('')}</div></details><p id="share-error" class="error" role="alert"></p><div class="actions modal-actions">${button('画像を保存','save-image','primary')}<a class="btn" id="share-x" target="_blank" rel="noopener noreferrer">Xに投稿する</a>${button('URLをコピー','copy-share','plain')}</div><details><summary>共有URLを見る</summary><textarea id="share-output" class="share-code" readonly aria-label="共有URL"></textarea></details>`);const update=()=>{const chosen=[...document.querySelectorAll('[data-share-tag]:checked')].map(el=>tags[Number(el.dataset.shareTag)]),url=location.origin+'/#share='+encodeResult(r,chosen);$('#share-output').value=url;$('#share-x').href='https://twitter.com/intent/tweet?'+new URLSearchParams({text:`私の性癖タイプは「${r.title}」。${r.shadow?'\n'+r.shadow.text:''}\n#HEKI16 #性癖診断`,url});drawCard(r,chosen);};$('#share-tags').addEventListener('change',e=>{if(document.querySelectorAll('[data-share-tag]:checked').length>3){e.target.checked=false;$('#share-error').textContent='タグは3つまで選べます。';return;}$('#share-error').textContent='';update();});update();}
function drawCard(r,tags){const c=$('#share-canvas'),ctx=c.getContext('2d');ctx.fillStyle='#13111b';ctx.fillRect(0,0,1200,630);ctx.fillStyle='#b99ae6';ctx.font='700 28px sans-serif';ctx.fillText('HEKI16',64,70);ctx.textAlign='right';ctx.fillStyle='#bcb4ca';ctx.font='24px sans-serif';ctx.fillText(r.typeCode||'あなたの性癖',1136,70);ctx.textAlign='left';const wrap=(text,width)=>{const lines=[];let line='';for(const {segment:ch} of new Intl.Segmenter('ja',{granularity:'word'}).segment(text)){if(line&&ctx.measureText(line+ch).width>width&&!/^[、。！？）」』]/.test(ch)){lines.push(line);line='';}line+=ch;}if(line)lines.push(line);return lines;};ctx.fillStyle='#f4f0fa';ctx.font='700 64px sans-serif';const titleLines=wrap(r.title,1072);titleLines.forEach((line,i)=>ctx.fillText(line,64,175+i*76));const y=175+titleLines.length*76+26;ctx.fillStyle='#b99ae6';ctx.fillRect(64,y-2,4,120);ctx.fillStyle='#e4dceb';ctx.font='42px sans-serif';wrap(r.shadow?.text||r.description,1000).slice(0,2).forEach((line,i)=>ctx.fillText(line,88,y+42+i*56));ctx.fillStyle='#bcb4ca';ctx.font='25px sans-serif';let x=64;for(const t of tags){let label=(t.kind==='boundary'?'避けたい：':'#')+t.label;while(ctx.measureText(label).width>320)label=Array.from(label).slice(0,-2).join('')+'…';ctx.fillText(label,x,516);x+=ctx.measureText(label).width+28;}ctx.strokeStyle='#393147';ctx.beginPath();ctx.moveTo(64,550);ctx.lineTo(1136,550);ctx.stroke();ctx.font='22px sans-serif';ctx.fillText('あなたの性癖に、名前をつける。',64,590);ctx.textAlign='right';ctx.fillText('heki16-pro.aiyume.workers.dev',1136,590);ctx.textAlign='left';}
async function copy(value){try{await navigator.clipboard.writeText(value);say('コピーしました。');}catch{const output=$('#share-output');output.value=value;const details=output.closest('details');if(details)details.open=true;output.focus();output.select();say('この欄を選択してコピーしてください。');}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}

function research(){if(!SITEKEY||sample||shared||!state.complete||state.instrument!==INSTRUMENT)return;modal('回答の提供について',`<p>送るものは、今回の回答と、タグの分類ごとの個数です。名前・自由に書いたタグ・連絡先は送りません。</p><p>回答は180日を目安に自動削除し、質問の見直しと提供された回答の参考値に使います。広告の選別には使いません。取り消すと回答を削除します。</p><label class="check"><input id="research-consent" type="checkbox"><span>18歳以上で、<a href="/privacy/#research" target="_blank" rel="noopener">提供する情報と取り消し方法</a>を確認し、協力に同意します。</span></label><div id="turnstile-box"></div><p id="research-error" class="error" role="alert"></p>${button('同意して回答を提供する','submit-research','primary')}`);$('#modal [data-action="submit-research"]').disabled=true;$('#research-consent').addEventListener('change',async e=>{if(!e.target.checked){$('#modal [data-action="submit-research"]').disabled=true;return;}try{if(!window.turnstile)await new Promise((resolve,reject)=>{const existing=$('#turnstile-script');if(existing){existing.remove();}const script=document.createElement('script');script.id='turnstile-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=reject;document.head.append(script);});if($('#turnstile-box').dataset.loaded&&$('#turnstile-box').dataset.token){$('#modal [data-action="submit-research"]').disabled=false;}if(!$('#turnstile-box').dataset.loaded){$('#turnstile-box').dataset.loaded='true';activeWidget=window.turnstile.render('#turnstile-box',{sitekey:SITEKEY,action:'research',theme:'dark',size:'compact',callback:token=>{if(!$('#research-consent'))return;$('#turnstile-box').dataset.token=token;$('#research-error').textContent='';$('#modal [data-action="submit-research"]').disabled=!$('#research-consent').checked;},'expired-callback':()=>{if($('#turnstile-box'))$('#turnstile-box').dataset.token='';if($('#modal [data-action="submit-research"]'))$('#modal [data-action="submit-research"]').disabled=true;}});}}catch{$('#research-error').textContent='確認を読み込めませんでした。時間をおいてお試しください。';}});}
async function submitResearch(){const submit=$('#modal [data-action="submit-research"]');if(!$('#research-consent')?.checked||!$('#turnstile-box')?.dataset.token)return;submit.disabled=true;try{if(!receipt){const raw=crypto.getRandomValues(new Uint8Array(32));receipt={id:crypto.randomUUID(),deletionToken:btoa(String.fromCharCode(...raw)).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_'),pending:true};localStorage.setItem(RECEIPT,JSON.stringify(receipt));}const r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...receipt,pending:undefined,instrument:INSTRUMENT,consent:CONSENT,adult:true,mode:state.mode,answers:state.answers,groups:Object.keys(GROUPS).map(g=>state.tags.filter(t=>t.group===g).length),token:$('#turnstile-box').dataset.token})});if(!r.ok)throw Error('現在、回答を受け付けられません。時間をおいてお試しください。');receipt={id:receipt.id,deletionToken:receipt.deletionToken,accepted:true};localStorage.setItem(RECEIPT,JSON.stringify(receipt));close();say('ご協力ありがとうございます。いつでも取り消せます。');render();}catch(e){$('#research-error').textContent=e.message;$('#turnstile-box').dataset.token='';submit.disabled=true;if(activeWidget!==null&&window.turnstile)window.turnstile.reset(activeWidget);}}
async function withdraw(){const r=await fetch('/api/research/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:receipt.id,deletionToken:receipt.deletionToken})});if(!r.ok){say('取り消せませんでした。控えを残して、時間をおいてお試しください。');return;}localStorage.removeItem(RECEIPT);receipt=null;close();render();say('回答の提供を取り消しました。');}
async function reference(){const target=$('#reference-result');target.textContent='確認しています…';try{const r=await fetch('/api/reference');if(!r.ok)throw Error();const p=await r.json();target.textContent=p.ready?`${p.responsesAtLeast}件以上の協力回答による参考値です。同じ人の複数回答を含む可能性があり、一般の人全体を表すものではありません。`: '参考値は準備中です。今の自分の気持ちを大切にしてください。';}catch{target.textContent='今は確認できません。時間をおいてお試しください。';}}

function withdrawal(){return `<h1>提供した回答を取り消す</h1><p>保存した控えの内容を貼り付けてください。</p><label class="label" for="receipt-input">控えの内容</label><textarea id="receipt-input" rows="8" maxlength="65536"></textarea><p id="receipt-error" role="alert" class="error"></p>${button('控えを確認する','read-receipt','primary')}`;}
function render(preserve=false){const scroll=window.scrollY,open=preserve?[...document.querySelectorAll('main details')].map(d=>d.open):[],focusId=document.activeElement?.id,focusTag=document.activeElement?.dataset.tag,focusAction=document.activeElement?.dataset.action,route=location.hash.slice(1)||'home';shared=null;if(route.startsWith('share=')){try{shared=readResultLink(location.href);sample=false;}catch(e){$('#main').innerHTML=`<section class="hero"><h1>共有結果を読み取れませんでした。</h1><p>${esc(e.message)}</p>${button('性癖を診断する','start','primary')}</section>`;return;}}document.body.dataset.view=route==='quiz'?'quiz':'page';document.querySelectorAll('.site-header nav a').forEach(a=>{if(a.hash==='#'+(shared?'profile':route))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').classList.toggle('steady-update',preserve);$('#main').innerHTML=route==='withdraw'?withdrawal():route==='quiz'?(state.adult?quiz():profile()):route==='profile'||shared?profile():route==='compare'?compare():home();if(preserve){[...document.querySelectorAll('main details')].forEach((d,i)=>d.open=!!open[i]);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusTag!==undefined)document.querySelector('[data-tag="'+focusTag+'"]')?.focus({preventScroll:true});else if(focusAction)document.querySelector('[data-action="'+focusAction+'"]')?.focus({preventScroll:true});window.scrollTo(0,scroll);}else{($('#question-title')||$('#main')).focus({preventScroll:true});window.scrollTo(0,0);}}
document.addEventListener('change',e=>{if(e.target.name==='answer'){state.answers[QUESTION_ORDER[state.index]]=Number(e.target.value);persist();$('[data-action="next"]').disabled=false;}});
document.addEventListener('submit',e=>{if(e.target.id!=='tag-form')return;e.preventDefault();const label=normalizeLabel($('#tag-input').value);if(!label){say('タグの言葉を入力してください。');return;}if(state.tags.length>=24){say('タグは24個まで。今あるタグを編集できます。');return;}undoTags=structuredClone(state.tags);state.tags=organizeTags([...state.tags,{label,kind:$('#tag-kind').value}],state.learned);persist();render(true);$('#tag-input').focus({preventScroll:true});say('タグを追加しました。');});
document.addEventListener('click',async e=>{if(e.target.closest('a[href="#main"]')){e.preventDefault();$('#main').focus();return;}const suggested=e.target.closest('[data-suggest-tag]');if(suggested){if(state.tags.length>=24){say('タグは24個まで。');return;}undoTags=structuredClone(state.tags);state.tags=organizeTags([...state.tags,{label:suggested.dataset.suggestTag,kind:'like'}],state.learned);persist();render(true);say('選んだ言葉を追加しました。');return;}const tag=e.target.closest('button[data-tag]');if(tag){editTag(Number(tag.dataset.tag));return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;try{switch(action){
case 'start':start();break;
case 'confirm-start':if(!$('#adult-check').checked){$('#start-error').textContent='18歳以上の方が対象です。';return;}state={...empty(),tags:state.tags,learned:state.learned,adult:true};sample=false;shared=null;persist();close();navigate('quiz');break;
case 'resume':sample=false;navigate('quiz');break;case 'sample':sample=true;navigate('profile');break;case 'pause':persist();navigate('home');break;case 'next':advance();break;case 'skip':advance(true);break;case 'previous':state.index=Math.max(0,state.index-1);persist();render();break;case 'review':state.index=0;sample=false;navigate('quiz');break;
case 'compare':if(shared)keepPartner(encodeResult(shared,shared.tags));navigate('compare');break;case 'run-compare':runCompare();break;case 'share':share();break;case 'copy-share':await copy($('#share-output').value);break;case 'save-image':$('#share-canvas').toBlob(blob=>download(blob,'heki16-'+(currentResult().typeCode||'result')+'.png'),'image/png');break;
case 'organize':undoTags=structuredClone(state.tags);state.tags=organizeTags(state.tags,state.learned);persist();render(true);say('タグを整理しました。');break;case 'undo-tags':if(undoTags){state.tags=undoTags;undoTags=null;persist();render(true);say('直前のタグに戻しました。');}break;
case 'save-tag':{const index=Number($('#modal').dataset.tag),label=normalizeLabel($('#edit-label').value);if(!label){say('タグの言葉を入力してください。');return;}undoTags=structuredClone(state.tags);const group=$('#edit-group').value;state.learned[label]=group;state.tags[index]={label,group,kind:$('#edit-kind').value,manual:true};state.tags=organizeTags(state.tags,state.learned);persist();close();render(true);say('タグを保存しました。');break;}
case 'delete-tag':undoTags=structuredClone(state.tags);state.tags.splice(Number($('#modal').dataset.tag),1);persist();close();render(true);say('タグを削除しました。元に戻せます。');break;
case 'backup':download(new Blob([JSON.stringify({state,receipt},null,2)],{type:'application/json'}),'heki16-private-backup.json');break;case 'reset':modal('回答とタグを消しますか？',`<p>このブラウザーの回答とタグを消します。先にデータを保存することもできます。</p><div class="actions">${button('データを保存','backup')}${button('回答を消す','confirm-reset','plain')}${button('戻る','close','plain')}</div>`);break;case 'confirm-reset':state=empty();sample=false;shared=null;persist();close();navigate('home');break;
case 'read-receipt':{try{const r=JSON.parse($('#receipt-input').value).receipt;if(!r||!/^[-a-f0-9]{36}$/i.test(r.id)||!/^[A-Za-z0-9_-]{43}$/.test(r.deletionToken))throw Error();receipt={id:r.id,deletionToken:r.deletionToken};modal('提供した回答を取り消しますか？',`<p>提供した回答を削除します。手元の診断結果は残ります。</p><div class="actions">${button('提供を取り消す','confirm-withdraw')}${button('戻る','close','plain')}</div>`);}catch{$('#receipt-error').textContent='控えの内容を確認してください。';}break;}
case 'research':research();break;case 'submit-research':await submitResearch();break;case 'withdraw':modal('提供した回答を取り消しますか？',`<p>提供した回答を削除します。手元の診断結果は残ります。</p><div class="actions">${button('提供を取り消す','confirm-withdraw')}${button('戻る','close','plain')}</div>`);break;case 'confirm-withdraw':await withdraw();break;case 'reference':await reference();break;case 'close':close();break;
}}catch{say('操作を完了できませんでした。もう一度お試しください。');}});
window.addEventListener('hashchange',()=>{if(!['#profile','#compare'].includes(location.hash))sample=false;render();});render();
